      },
      host: '[::1]:8080',
      hostname: '[::1]',
      port: 8080
    },
    {
      name: 'multiple x-forwarded-host entries',
      trustProxy: true,
      headers: {
        host: 'real.test:3000',
        'x-forwarded-host': 'first.test:8080, fastify.test:9090'
      },
      host: 'fastify.test:9090',
      hostname: 'fastify.test',
